local ADDON, ns = ...
local L = ns.L

L.RB_PAGE_TITLE = "Your duties and permissions"
L.RB_PAGE_NOTE = "Personal briefings for offices this character actually holds. They remain here after you read them. A preview never creates a letter or grants authority."
L.RB_LINK = "Duty letters"
L.RB_BACK = "< All duty letters"
L.RB_REALM_BACK = "< Back to the Realm"
L.RB_NONE = "No duty letter is held for this character."
L.RB_READY = "A new duty letter is ready: %s. Open it with /oly duties."
L.RB_HELP = "  /oly duties - reopen your appointment, office and recruiting briefings"
L.RB_APPOINTED = "Recorded for %s on %s. This explains the tools the role grants in Olympus; native guild actions still require your own click in WoW."
L.RB_CHECKLIST = "Practical checklist"
L.RB_CHURCH_CHECKLIST_LINK = "Open recruiting checklist"
L.RB_CHURCH_CHECKLIST_TIP = "Reopen your personal steps for inviting, registering, confirming and following a recruit."

L.RB_TITLE_KING = "The King's briefing"
L.RB_KING_1 = "The Crown coordinates the army through the Throne: decrees, the King's Week, calls to Court, Vox Populi, Hands and the offices explicitly entrusted to them. Every public action remains attributable; a preview has no power."
L.RB_KING_2 = "Review the Realm, The Watch and Treasury before acting. Missing or relayed information can be unknown; never treat silence as proof. Native invites, removals, trades and mail remain manual."
L.RB_KING_3 = "For stream privacy, use Private presence in My profile or /oly presence on. Olympus first withdraws your shared location, then stops its cross-guild online announcements for this session. Your own guild still sees Blizzard's normal guild-roster presence."

L.RB_TITLE_COUNCIL = "High Council briefing"
L.RB_COUNCIL_1 = "Signed High Council members may use the council rooms and the tools of their verified department, assist the Crown where the interface explicitly permits it, and review the shared operational picture. A title preview or a relayed claim grants nothing."
L.RB_COUNCIL_2 = "Use The Watch only when your current role actually grants its desk. Keep moderation, Justice and Treasury records within their displayed audiences; do not copy private evidence into public chat."
L.RB_COUNCIL_3 = "Private presence is available in My profile or with /oly presence on. It hides Olympus's cross-guild online and location conveniences for this session, while your own guild's native roster still works."

L.RB_TITLE_STEWARD = "Steward briefing"
L.RB_STEWARD_1 = "The Steward helps maintain the Crown's operational lists and the actions the Throne explicitly lends. The interface labels each action you may take; being Steward does not make you King or High Council."
L.RB_STEWARD_2 = "Confirm the current signed source before changing a list. Missing evidence remains unknown, and no native guild, trade, mail or moderation action is automatic."

L.RB_TITLE_HAND = "Hand of the King briefing"
L.RB_HAND_1 = "A Hand carries the Crown's voice only through the actions the Throne explicitly lends. Use calls, rooms and pins for their stated audience, and keep the original sender and purpose clear."
L.RB_HAND_2 = "A Hand is not automatically High Council, Treasurer or The Watch. The addon checks each permission separately; native game actions still require your own click."

L.RB_TITLE_GM = "Guild Master briefing"
L.RB_GM_1 = "Your Guild tab manages this Olympus guild's structure: appoint up to 25 Legates, each coordinating an agreed group of 40 including the Legate, and one correspondent for each department. Appointments do not promote, invite or remove anyone in WoW."
L.RB_GM_2 = "Use the roster, War Room, charter, muster and guild-local moderation tools for your own guild. Check freshness and signatures before relying on a relayed list; missing data is unknown, not zero."
L.RB_GM_3 = "Legate groups are flexible. Members may join another leader when theirs is offline. Your job is to keep responsibilities clear and coordinate attendance, not to build a rigid automatic hierarchy."

L.RB_TITLE_WATCH = "The Watch briefing"
L.RB_WATCH_1 = "The Watch is a private, guild-local desk for reports, cases, chat evidence and explicit Justice requests that your current verified role may read. A council preview, relayed rank or old appointment never grants access."
L.RB_WATCH_2 = "Review the evidence and its source before a manual game action. The addon can record, relay and explain a request; it never automatically mutes, removes, punishes or declares someone guilty."
L.RB_WATCH_3 = "Keep case details inside The Watch. Close or resolve a record only through the displayed workflow so its authorship and audit history remain intact."

L.RB_TITLE_TREASURER = "Treasurer briefing"
L.RB_TREASURER_1 = "The Treasury separates confirmed native receipts, manual notes, expenses and unknown coverage. Share only through the consented book tools; a sent mail or a typed line is not proof that gold was received."
L.RB_TREASURER_2 = "The addon may prepare an amount or retain a receipt, but it never sends mail, accepts a trade, withdraws bank gold or moves funds by itself. Review the guild and audience on every page before sharing."

L.RB_TITLE_APOSTLE = "Apostle briefing"
L.RB_APOSTLE_1 = "An Apostle builds a missionary network and may name missionaries within the Church's current personal and global limits. Use Church > Mine to review your place, registrations, credited recruits and retained evidence."
L.RB_APOSTLE_2 = "Only register someone you personally brought. The normal Blizzard invite remains manual, and the recruit counts only after the Church's confirmation and retention rules are satisfied. Missing coverage is unknown, not a failed recruit."
L.RB_APOSTLE_3 = "Open the recruiting checklist below whenever you recruit or help a missionary."

L.RB_TITLE_MISSIONARY = "Missionary recruiting briefing"
L.RB_MISSIONARY_1 = "A Missionary brings new members, records only their own recruits and helps the Church keep enough independent evidence to confirm them. The addon does not invite anyone automatically."
L.RB_MISSIONARY_2 = "Use this checklist each time:"
L.RB_MISSIONARY_C1 = "1. Open Church > Mine and confirm that your role and network are shown."
L.RB_MISSIONARY_C2 = "2. Speak with the recruit and invite them through Blizzard's normal guild interface."
L.RB_MISSIONARY_C3 = "3. In Church > Mine, choose Register a recruit and enter the person you personally brought."
L.RB_MISSIONARY_C4 = "4. When practical, keep another updated guild client online so the join can be independently confirmed; retained valid evidence may relay later if you miss each other."
L.RB_MISSIONARY_C5 = "5. Reopen Mine and distinguish pending, credited and retained after seven days. Missing evidence remains pending or unknown, never invented."
L.RB_MISSIONARY_C6 = "6. If your role allows naming missionaries, use the Church's Name action within the displayed quota; talk to them before assigning the duty."

L.RB_TITLE_CHURCH_CORR = "Church correspondent briefing"
L.RB_CHURCH_CORR_1 = "The Church correspondent watches the current guild's membership coverage and relays its verified Church facts. The streak belongs to your own appointment; it is not inherited from a previous correspondent."
L.RB_CHURCH_CORR_2 = "An unknown day pauses without points and without erasing a proved streak. An observed day below the displayed threshold breaks it. Report what the client can support, never a guessed total."

L.RB_TITLE_LEGATE = "Legate briefing"
L.RB_LEGATE_1 = "A Legate organizes an agreed raid group of 40: the Legate and up to 39 guildmates. Speak with them, maintain your group in the War Room and coordinate attendance at events, raids and wars."
L.RB_LEGATE_2 = "The structure is guidance, not a lock. Members may play under another leader when you are offline, and another Legate may help fill the event. No guild invite, removal, promotion or raid invite is automatic."
L.RB_LEGATE_3 = "The Legate badge and this appointment follow the High Council's current structure; the former wingless bronze office frame is not the Legate identity."

L.RB_TITLE_CORRESPONDENT = "%s correspondent briefing"
L.RB_CORRESPONDENT_1 = "You are the Guild Master's named correspondent for %s. Your access and audience are limited to that department and this current appointment."
L.RB_CORRESPONDENT_2 = "Department purpose: %s"
L.RB_CORRESPONDENT_3 = "Use the department page to carry verified information between your guild and its responsible office. A relayed appointment does not grant native guild powers, and the addon never performs those actions for you."

if GetLocale and GetLocale() == "ptBR" then
	L.RB_PAGE_TITLE = "Seus deveres e permissões"
	L.RB_PAGE_NOTE = "Briefings pessoais dos cargos que este personagem realmente ocupa. Eles continuam aqui depois de lidos. Uma prévia nunca cria carta nem dá autoridade."
	L.RB_LINK = "Cartas de deveres"
	L.RB_BACK = "< Todas as cartas de deveres"
	L.RB_REALM_BACK = "< Voltar ao Reino"
	L.RB_NONE = "Nenhuma carta de dever está guardada para este personagem."
	L.RB_READY = "Uma nova carta de dever está pronta: %s. Abra com /oly duties."
	L.RB_HELP = "  /oly duties - reabrir seus briefings de nomeação, cargo e recrutamento"
	L.RB_APPOINTED = "Registrado para %s em %s. Isto explica as ferramentas que o cargo libera no Olympus; ações nativas da guilda ainda exigem seu próprio clique no WoW."
	L.RB_CHECKLIST = "Checklist prático"
	L.RB_CHURCH_CHECKLIST_LINK = "Abrir checklist de recrutamento"
	L.RB_CHURCH_CHECKLIST_TIP = "Reabra seus passos pessoais para convidar, registrar, confirmar e acompanhar um recruta."

	L.RB_TITLE_KING = "Briefing do Rei"
	L.RB_KING_1 = "A Coroa coordena o exército pelo Trono: decretos, King's Week, chamados à Corte, Vox Populi, Mãos e os cargos confiados explicitamente. Toda ação pública continua atribuída; uma prévia não tem poder."
	L.RB_KING_2 = "Revise o Reino, The Watch e o Tesouro antes de agir. Informação ausente ou repassada pode ser desconhecida; nunca trate silêncio como prova. Convites, remoções, trocas e correio nativos continuam manuais."
	L.RB_KING_3 = "Para privacidade em stream, use Presença privada em Meu perfil ou /oly presence on. O Olympus primeiro retira sua localização compartilhada e depois para de anunciá-lo online entre guildas nesta sessão. Sua própria guilda ainda vê o roster nativo do WoW."
	L.RB_TITLE_COUNCIL = "Briefing do High Council"
	L.RB_COUNCIL_1 = "Membros assinados do High Council podem usar as salas do conselho e as ferramentas do seu departamento verificado, ajudar a Coroa onde a interface permite e revisar o quadro operacional compartilhado. Prévia de cargo ou alegação repassada não dá poder."
	L.RB_COUNCIL_2 = "Use The Watch apenas quando seu cargo atual realmente liberar a mesa. Mantenha registros de moderação, Justiça e Tesouro dentro do público exibido; não copie prova privada para o chat público."
	L.RB_COUNCIL_3 = "Presença privada fica em Meu perfil ou /oly presence on. Ela oculta as facilidades de online e localização entre guildas nesta sessão, enquanto o roster nativo da sua guilda continua funcionando."
	L.RB_TITLE_STEWARD = "Briefing do Steward"
	L.RB_STEWARD_1 = "O Steward ajuda a manter as listas operacionais da Coroa e as ações que o Trono empresta explicitamente. A interface identifica cada ação permitida; ser Steward não torna alguém Rei nem High Council."
	L.RB_STEWARD_2 = "Confirme a fonte assinada atual antes de alterar uma lista. Prova ausente continua desconhecida, e nenhuma ação nativa de guilda, troca, correio ou moderação é automática."
	L.RB_TITLE_HAND = "Briefing da Mão do Rei"
	L.RB_HAND_1 = "Uma Mão leva a voz da Coroa somente pelas ações que o Trono empresta explicitamente. Use chamados, salas e pins para o público indicado e mantenha claro o remetente e o propósito originais."
	L.RB_HAND_2 = "Uma Mão não é automaticamente High Council, Tesoureiro nem The Watch. O addon verifica cada permissão separadamente; ações nativas do jogo ainda exigem seu próprio clique."
	L.RB_TITLE_GM = "Briefing do Guild Master"
	L.RB_GM_1 = "Sua aba Guilda organiza esta guilda Olympus: nomeie até 25 Legates, cada um coordenando um grupo combinado de 40 incluindo o Legate, e um correspondente por departamento. Nomeações não promovem, convidam nem removem ninguém no WoW."
	L.RB_GM_2 = "Use o roster, a Sala de Guerra, charter, muster e moderação local para sua própria guilda. Confira atualização e assinaturas antes de confiar numa lista repassada; dado ausente é desconhecido, não zero."
	L.RB_GM_3 = "Grupos de Legates são flexíveis. Membros podem seguir outro líder quando o seu estiver offline. Seu papel é deixar responsabilidades claras e coordenar presença, não criar uma hierarquia automática rígida."
	L.RB_TITLE_WATCH = "Briefing da The Watch"
	L.RB_WATCH_1 = "The Watch é uma mesa privada e local da guilda para reports, casos, prova do chat e pedidos explícitos da Justiça que seu cargo verificado atual pode ler. Prévia do conselho, rank repassado ou nomeação antiga nunca libera acesso."
	L.RB_WATCH_2 = "Revise a prova e sua fonte antes de uma ação manual no jogo. O addon pode registrar, repassar e explicar um pedido; nunca silencia, remove, pune ou declara culpa automaticamente."
	L.RB_WATCH_3 = "Mantenha detalhes do caso dentro da The Watch. Feche ou resolva um registro somente pelo fluxo exibido para preservar autoria e auditoria."
	L.RB_TITLE_TREASURER = "Briefing do Tesoureiro"
	L.RB_TREASURER_1 = "O Tesouro separa recibos nativos confirmados, notas manuais, despesas e cobertura desconhecida. Compartilhe somente pelas ferramentas consentidas dos livros; correio enviado ou linha digitada não prova ouro recebido."
	L.RB_TREASURER_2 = "O addon pode preparar um valor ou guardar um recibo, mas nunca envia correio, aceita troca, saca ouro do banco ou movimenta recursos sozinho. Confira a guilda e o público em cada página antes de compartilhar."
	L.RB_TITLE_APOSTLE = "Briefing de Apóstolo"
	L.RB_APOSTLE_1 = "Um Apóstolo constrói uma rede missionária e pode nomear missionários dentro dos limites pessoal e global atuais da Igreja. Use Igreja > Meus dados para revisar seu lugar, registros, recrutas creditados e provas guardadas."
	L.RB_APOSTLE_2 = "Registre apenas quem você trouxe pessoalmente. O convite normal do WoW continua manual, e o recruta só conta depois das regras de confirmação e retenção da Igreja. Cobertura ausente é desconhecida, não recrutamento fracassado."
	L.RB_APOSTLE_3 = "Reabra o checklist abaixo sempre que recrutar ou ajudar um missionário."
	L.RB_TITLE_MISSIONARY = "Briefing de recrutamento missionário"
	L.RB_MISSIONARY_1 = "Um Missionário traz membros novos, registra somente os próprios recrutas e ajuda a Igreja a guardar prova independente suficiente para confirmá-los. O addon não convida ninguém automaticamente."
	L.RB_MISSIONARY_2 = "Use este checklist a cada recrutamento:"
	L.RB_MISSIONARY_C1 = "1. Abra Igreja > Meus dados e confirme que seu cargo e sua rede aparecem."
	L.RB_MISSIONARY_C2 = "2. Converse com o recruta e convide pela interface normal de guilda do WoW."
	L.RB_MISSIONARY_C3 = "3. Em Igreja > Meus dados, escolha Registrar um recruta e informe a pessoa que você trouxe."
	L.RB_MISSIONARY_C4 = "4. Quando possível, mantenha outro cliente atualizado da guilda online para confirmar a entrada de forma independente; prova válida guardada pode ser repassada depois se vocês não se encontrarem online."
	L.RB_MISSIONARY_C5 = "5. Reabra Meus dados e diferencie resultados pendentes, creditados e mantidos após sete dias. Prova ausente continua pendente ou desconhecida, nunca inventada."
	L.RB_MISSIONARY_C6 = "6. Se seu cargo permitir nomear missionários, use a ação Nomear da Igreja dentro da quota exibida; converse com a pessoa antes de atribuir o dever."
	L.RB_TITLE_CHURCH_CORR = "Briefing de correspondente da Igreja"
	L.RB_CHURCH_CORR_1 = "O correspondente da Igreja acompanha a cobertura de membros da guilda atual e repassa fatos verificados da Igreja. A sequência pertence à sua própria nomeação; não é herdada do correspondente anterior."
	L.RB_CHURCH_CORR_2 = "Um dia desconhecido pausa sem pontos e sem apagar uma sequência comprovada. Um dia observado abaixo do limite exibido interrompe. Informe somente o que o cliente consegue sustentar, nunca um total estimado."
	L.RB_TITLE_LEGATE = "Briefing de Legate"
	L.RB_LEGATE_1 = "Um Legate organiza um grupo de raide combinado de 40: o Legate e até 39 companheiros da guilda. Converse com eles, mantenha o grupo na Sala de Guerra e coordene presença em eventos, raides e guerras."
	L.RB_LEGATE_2 = "A estrutura é orientação, não trava. Membros podem jogar com outro líder quando você estiver offline, e outro Legate pode ajudar a completar o evento. Nenhum convite de guilda ou raide, remoção ou promoção é automático."
	L.RB_LEGATE_3 = "O badge de Legate e esta nomeação seguem a estrutura atual do High Council; a antiga borda bronze sem asas não é a identidade do Legate."
	L.RB_TITLE_CORRESPONDENT = "Briefing de correspondente de %s"
	L.RB_CORRESPONDENT_1 = "Você é o correspondente nomeado pelo Guild Master para %s. Seu acesso e público se limitam a esse departamento e à nomeação atual."
	L.RB_CORRESPONDENT_2 = "Objetivo do departamento: %s"
	L.RB_CORRESPONDENT_3 = "Use a página do departamento para levar informação verificada entre sua guilda e o responsável. Uma nomeação repassada não dá poderes nativos da guilda, e o addon nunca executa essas ações por você."
end
